#include <vector>
#include <unordered_map>

class Solution {
public:
    int earliestSecondToMarkIndices(std::vector<int>& nums, std::vector<int>& changeIndices) {
        int n = nums.size(), m = changeIndices.size();
        auto check = [&](int t) {
            std::unordered_map<int, int> last;
            for (int s = 0; s < t; ++s) last[changeIndices[s]] = s;
            int decrement = 0, marked = 0;
            for (int s = 0; s < t; ++s) {
                int idx = changeIndices[s];
                if (last[idx] == s) {
                    if (decrement < nums[idx - 1]) return false;
                    decrement -= nums[idx - 1];
                    marked++;
                } else {
                    decrement++;
                }
            }
            return marked == n;
        };
        int l = 1, r = m, ans = -1;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            if (check(mid)) {
                ans = mid;
                r = mid - 1;
            } else l = mid + 1;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int earliestSecondToMarkIndices(int[] nums, int[] changeIndices) {
        int n = nums.length, m = changeIndices.length;
        int l = 1, r = m, ans = -1;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            if (check(mid, nums, changeIndices)) {
                ans = mid;
                r = mid - 1;
            } else l = mid + 1;
        }
        return ans;
    }

    private boolean check(int t, int[] nums, int[] changeIndices) {
        int n = nums.length;
        Map<Integer, Integer> last = new HashMap<>();
        for (int s = 0; s < t; ++s) last.put(changeIndices[s], s);
        int decrement = 0, marked = 0;
        for (int s = 0; s < t; ++s) {
            int idx = changeIndices[s];
            if (last.get(idx) == s) {
                if (decrement < nums[idx - 1]) return false;
                decrement -= nums[idx - 1];
                marked++;
            } else {
                decrement++;
            }
        }
        return marked == n;
    }
}

var earliestSecondToMarkIndices = function(nums, changeIndices) {
    const n = nums.length, m = changeIndices.length;
    const check = (t) => {
        const last = new Map();
        for (let s = 0; s < t; ++s) last.set(changeIndices[s], s);
        let decrement = 0, marked = 0;
        for (let s = 0; s < t; ++s) {
            const idx = changeIndices[s];
            if (last.get(idx) === s) {
                if (decrement < nums[idx - 1]) return false;
                decrement -= nums[idx - 1];
                marked++;
            } else {
                decrement++;
            }
        }
        return marked === n;
    };
    let l = 1, r = m, ans = -1;
    while (l <= r) {
        const mid = Math.floor((l + r) / 2);
        if (check(mid)) {
            ans = mid;
            r = mid - 1;
        } else l = mid + 1;
    }
    return ans;
};
